danger_label","component":"Text","content":"危险","styles":{"width":60,"height":16,"fontSize":14,"fontWeight":700,"fontColor":"#ffffffff","maxLines":1}},{"id":"alert_value","component":"Text","content":"{{ ${/data/weather/current/alertLevel} }}","styles":{"width":60,"height":14,"fontSize":10,"fontWeight":500,"fontColor":"#ffffffff","maxLines":1}},{"id":"action_button","component":"Button","label":"打开","onClick":[{"call":"clickToDeeplink","args":{"bundleName":"com.huawei.hmos.settings","abilityName":"com.huawei.hmos.settings.MainAbility","uri":"intelligent_scene_entry"}}],"styles":{"width":52,"height":32,"borderRadius":16,"backgroundColor":"#ffffffff","fontSize":12,"fontWeight":"medium","fontColor":"#e64566"}}]}}
